"use client";
import { useState, useRef, useEffect, useCallback } from "react";
import Image from "next/image";

type GalleryImage = {
  id: number;
  url: string;
  thumb_url: string;
  name: string;
};

export default function MuseumGallery({
  images,
  museumName,
}: {
  images: GalleryImage[];
  museumName: string;
}) {
  const [activeIndex, setActiveIndex] = useState(0);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(false);
  const thumbsRef = useRef<HTMLDivElement>(null);
  const thumbRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const updateScrollState = useCallback(() => {
    const el = thumbsRef.current;
    if (!el) return;
    setCanScrollLeft(el.scrollLeft > 4);
    setCanScrollRight(el.scrollLeft + el.clientWidth < el.scrollWidth - 4);
  }, []);

  useEffect(() => {
    updateScrollState();
    const el = thumbsRef.current;
    if (!el) return;
    el.addEventListener("scroll", updateScrollState, { passive: true });
    return () => el.removeEventListener("scroll", updateScrollState);
  }, [updateScrollState, images]);

  // Active thumbnail değişince otomatik scroll
  useEffect(() => {
    const thumb = thumbRefs.current[activeIndex];
    const container = thumbsRef.current;
    if (!thumb || !container) return;

    const thumbLeft = thumb.offsetLeft;
    const thumbWidth = thumb.offsetWidth;
    const containerWidth = container.clientWidth;
    const targetScroll = thumbLeft - containerWidth / 2 + thumbWidth / 2;

    container.scrollTo({ left: targetScroll, behavior: "smooth" });
  }, [activeIndex]);

  if (images.length === 0) {
    return (
      <div
        className="tw-rounded-xl tw-bg-gray-100 tw-flex tw-items-center tw-justify-center tw-text-gray-400"
        style={{ height: 420 }}
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" fill="currentColor" viewBox="0 0 16 16">
          <path d="M2 1a1 1 0 0 0-1 1v12a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V2a1 1 0 0 0-1-1H2zm6 1 6 3H2L8 2zm-5 4h2v7H3V6zm4 0h2v7H7V6zm4 0h2v7h-2V6z" />
        </svg>
      </div>
    );
  }

  return (
    <div>
      {/* Main image */}
      <div className="tw-relative tw-rounded-xl tw-overflow-hidden tw-shadow-md" style={{ height: 420 }}>
        <Image
          key={images[activeIndex].id}
          src={images[activeIndex].url}
          alt={images[activeIndex].name || museumName}
          fill
          className="tw-object-cover"
          quality={90}
        />
        {images.length > 1 && (
          <>
            <button
              onClick={() => setActiveIndex((i) => (i - 1 + images.length) % images.length)}
              className="tw-absolute tw-left-3 tw-top-1/2 tw--translate-y-1/2 tw-bg-black/40 hover:tw-bg-black/60 tw-text-white tw-rounded-full tw-w-9 tw-h-9 tw-flex tw-items-center tw-justify-center tw-transition-colors tw-border-0"
              aria-label="Previous"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16">
                <path fillRule="evenodd" d="M11.354 1.646a.5.5 0 0 1 0 .708L5.707 8l5.647 5.646a.5.5 0 0 1-.708.708l-6-6a.5.5 0 0 1 0-.708l6-6a.5.5 0 0 1 .708 0z" />
              </svg>
            </button>
            <button
              onClick={() => setActiveIndex((i) => (i + 1) % images.length)}
              className="tw-absolute tw-right-3 tw-top-1/2 tw--translate-y-1/2 tw-bg-black/40 hover:tw-bg-black/60 tw-text-white tw-rounded-full tw-w-9 tw-h-9 tw-flex tw-items-center tw-justify-center tw-transition-colors tw-border-0"
              aria-label="Next"
            >
              <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16">
                <path fillRule="evenodd" d="M4.646 1.646a.5.5 0 0 1 .708 0l6 6a.5.5 0 0 1 0 .708l-6 6a.5.5 0 0 1-.708-.708L10.293 8 4.646 2.354a.5.5 0 0 1 0-.708z" />
              </svg>
            </button>
            <span className="tw-absolute tw-bottom-3 tw-right-3 tw-bg-black/50 tw-text-white tw-text-xs tw-px-2 tw-py-1 tw-rounded-full">
              {activeIndex + 1} / {images.length}
            </span>
          </>
        )}
      </div>

      {/* Thumbnails */}
      {images.length > 1 && (
        <div className="tw-relative tw-mt-3">
          {/* Sol gradient */}
          <div
            className="tw-absolute tw-left-0 tw-top-0 tw-bottom-0 tw-w-10 tw-pointer-events-none tw-z-10 tw-transition-opacity tw-duration-200"
            style={{
              background: "linear-gradient(to right, rgba(255,255,255,0.95), transparent)",
              opacity: canScrollLeft ? 1 : 0,
            }}
          />
          {/* Sağ gradient */}
          <div
            className="tw-absolute tw-right-0 tw-top-0 tw-bottom-0 tw-w-10 tw-pointer-events-none tw-z-10 tw-transition-opacity tw-duration-200"
            style={{
              background: "linear-gradient(to left, rgba(255,255,255,0.95), transparent)",
              opacity: canScrollRight ? 1 : 0,
            }}
          />

          <div
            ref={thumbsRef}
            className="tw-flex tw-gap-2 tw-overflow-x-auto"
            style={{ scrollbarWidth: "none" }}
          >
            {images.map((img, i) => (
              <button
                key={img.id}
                ref={(el) => { thumbRefs.current[i] = el; }}
                onClick={() => setActiveIndex(i)}
                className="tw-relative tw-rounded-lg tw-overflow-hidden tw-border-2 tw-transition-all tw-p-0 tw-bg-transparent"
                style={{
                  width: 76,
                  height: 56,
                  flexShrink: 0,
                  borderColor: i === activeIndex ? "#854ec9" : "transparent",
                }}
                aria-label={`Go to image ${i + 1}`}
              >
                <Image
                  src={img.thumb_url || img.url}
                  alt={img.name || museumName}
                  fill
                  className="tw-object-cover"
                  loading="lazy"
                />
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
